      ,CO.RPRSNTV_NM = #{RPRSNTV_NM}
      ,CO.NATION_CODE = #{NATION_CODE}
      ,CO.BIZRNO = #{BIZRNO}
      ,CO.ZIP = #{ZIP}
      ,CO.ADRES = #{ADRES}
      ,CO.TELNO_1 = #{TELNO_1}
      ,CO.FXNUM = #{FXNUM}
