      ,CO.ACNUTNO = #{ACNUTNO}
      ,CO.BANK_CODE = #{BANK_CODE}
      ,CO.UNIPASS_ID = #{UNIPASS_ID}
      ,CO.UNIPASS_DOC_BOX_CODE = #{UNIPASS_DOC_BOX_CODE}
      ,CO.DRWBAK_SE_CODE = #{DRWBAK_SE_CODE}
      ,CO.RTROACT_PD = #{RTROACT_PD}
      ,CO.REQREQY_CALC_MTH = #{REQREQY_CALC_MTH}
      ,CO.PRIC_RQEST_TYPE = #{PRIC_RQEST_TYPE}
 WHERE CO.COMPANY_CODE = #{COMPANY_CODE}

