SELECT CU.COMPANY_CODE ,CU.CUSTOMER_CODE ,CU.REPRSNT_CUSTOMER_CODE ,CU.ECTMRK ,CU.ATTRIBUTE01 ,CU.RPRSNTV_NM ,CU.NATION_CODE ,FC01_GET_CODE_NM('NA',CU.NATION_CODE) NATION_NM ,CU.BIZRNO ,CU.ZIP ,CU.ADRES ,CU.TELNO_1 ,CU.TELNO_2 ,CU.FXNUM ,CU.EMAIL_ADRES ,CU.EXCL_AT ,CU.DELETE_DRCTR FROM CUSTOMER CU WHERE CU.COMPANY_CODE = #{COMPANY_CODE}
AND NVL(CU.DELETE_DRCTR,'N') = #{SEARCH_DELETE_DRCTR}
AND CU.CUSTOMER_CODE = #{SEARCH_KEY_WORD}
AND CU.CUSTOMER_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND CU.CUSTOMER_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND CU.ATTRIBUTE01 = #{SEARCH_KEY_WORD}
AND CU.ATTRIBUTE01 LIKE #{SEARCH_KEY_WORD}|| '%'
AND CU.ATTRIBUTE01 LIKE '%'||#{SEARCH_KEY_WORD}|| '%'

