SELECT DLR.COMPANY_CODE ,DLR.DRWBAK_LMTT_REGLTN ,FC01_GET_CODE_NM('DL',DLR.DRWBAK_LMTT_REGLTN) DRWBAK_LMTT_REGLTN_NM ,DLR.HS_CODE ,DLR.EFECT_BGNDE ,DLR.EFECT_ENDDE ,DLR.RM FROM DRWBAK_LMTT_REGLTN DLR WHERE DLR.COMPANY_CODE = #{COMPANY_CODE}
AND DLR.DRWBAK_LMTT_REGLTN = #{SEARCH_DRWBAK_LMTT_REGLTN}
AND DLR.HS_CODE LIKE #{SEARCH_HS_CODE} || '%'
AND #{SEARCH_YYYYMMDD} BETWEEN DLR.EFECT_BGNDE AND DLR.EFECT_ENDDE

SELECT DLR.COMPANY_CODE
      ,DLR.DRWBAK_LMTT_REGLTN
      ,DLR.HS_CODE
      ,DLR.EFECT_BGNDE
      ,DLR.EFECT_ENDDE
      ,DLR.RM
  FROM DRWBAK_LMTT_REGLTN DLR
 WHERE DLR.COMPANY_CODE = #{COMPANY_CODE}
   AND DLR.DRWBAK_LMTT_REGLTN = #{DRWBAK_LMTT_REGLTN}
   AND DLR.HS_CODE = #{HS_CODE}
   AND DLR.EFECT_BGNDE = #{EFECT_BGNDE}

