   AND DLR.DRWBAK_LMTT_REGLTN = #{DRWBAK_LMTT_REGLTN}
   AND DLR.HS_CODE = #{HS_CODE}
   AND DLR.EFECT_BGNDE = #{EFECT_BGNDE}

